function SortControlsDemo() {
  const [value, setValue] = useState<SortState>({
    id: "name",
    direction: "asc",
  });
  const rows = [
    { name: "Vendor 12", balance: 8500 },
    { name: "Vendor 2", balance: 12000 },
    { name: "Vendor 1", balance: 3000 },
  ];
  const sorted = sortRows(
    rows,
    (row) => (value.id === "balance" ? row.balance : row.name),
    value.direction,
  );
  return (
    <Stack>
      <SortMenu
        fields={[
          { id: "name", label: "Name" },
          { id: "balance", label: "Balance" },
        ]}
        value={value}
        onValueChange={setValue}
      />
      <ul>
        {sorted.map((row) => (
          <li key={row.name}>
            {row.name}: <Money value={row.balance} />
          </li>
        ))}
      </ul>
    </Stack>
  );
}

