  const [sort, setSort] = useState<SortState>({
    id: "name",
    direction: "asc",
  });
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<string[]>([]);
  const [tab, setTab] = useState("all");
  const visible = filterRows(
    searchRows(rows, query, [(row) => row.name, (row) => row.location]),
    filters,
    { service: (row) => row.service },
  );
  const sorted = sortRows(
    visible,
    (row) => (sort.id === "balance" ? row.balance : row.name),
    sort.direction,
  );
  const updateFilters = (next: FilterValue) => {
    setFilters(next);
    setPage(1);
  };
  const updateSort = (next: SortState) => {
    setSort(next);
    setPage(1);
  };
  const clearAll = () => {
    setQuery("");
    setPage(1);
  };
  return (
    <ListPageTemplate
      header={
        <PageHeader
          title="Vendors"
          count={rows.length}
          description="Manage accommodation, transport and activity partners."
        />
      }
      tabs={
        <TabBar
          aria-label="Vendor views"
          value={tab}
          onValueChange={setTab}
          items={[{ value: "all", label: "All vendors", count: rows.length }]}
        />
      }
      toolbar={
        <ListToolbar
          search={
            <SearchField
              placeholder="Search vendors"
              shortcut=""
              value={query}
              onValueChange={(next) => {
                setQuery(next);
                setPage(1);
              }}
            />
          }
          filters={
            <FilterMenu
              groups={groups}
              value={filters}
              onValueChange={updateFilters}
              onClearAll={clearAll}
            />
          }
          sort={
            <SortMenu
              fields={[
                { id: "name", label: "Name" },
                { id: "balance", label: "Balance" },
              ]}
              value={sort}
              onValueChange={updateSort}
            />
          }
          chips={
            <FilterChips
              groups={groups}
              value={filters}
              onValueChange={updateFilters}
              onClearAll={clearAll}
            />
          }
        />
      }
      bulkActions={
        <BulkActionBar
          count={selected.length}
          onClear={() => setSelected([])}
        >
          <span>Selected across pages</span>
        </BulkActionBar>
      }
      footer={
        <TableFooter
          page={page}
          pageSize={3}
          total={visible.length}
          onPageChange={setPage}
        />
      }
    >
      <DataTable
        caption="Vendors"
        rows={paginate(sorted, page, 3)}
        getRowId={(row) => row.id}
        selected={selected}
        onSelectionChange={setSelected}
        sort={sort}
        onSortChange={updateSort}
        columns={[
          {
            id: "name",
            header: "Vendor",
            sortValue: (row) => row.name,
            render: (row) => (
              <EntityCell name={row.name} description={row.id} />
            ),
          },
          {
            id: "location",
            header: "Location",
            render: (row) => (
              <IconTextCell icon="map-pin">{row.location}</IconTextCell>
            ),
          },
          {
            id: "balance",
            header: "Balance",
            align: "right",
            sortValue: (row) => row.balance,
            render: (row) => <Money value={row.balance} />,
          },
        ]}
      />
    </ListPageTemplate>
  );
}

